// element to be written. Thus the queue can only contain
// SB_QUEUE_TEMPCONTROL_SYSVERIF_FANACK_1_SIZE-1 elements.
#define SB_QUEUE_TEMPCONTROL_SYSVERIF_FANACK_1_SIZE 2

