use data::*;

use proptest::prelude::*;

pub fn option_strategy_default
  <T: Clone + std::fmt::Debug, 
   S:  Strategy<Value = T>> (base: S) -> impl Strategy<Value = Option<T>>
{
  option_strategy_bias(1, base)
}

pub fn option_strategy_bias
  <T: Clone + std::fmt::Debug, 
   S:  Strategy<Value = T>> (
  bias: u32,
  base: S) -> impl Strategy<Value = Option<T>>
{
  prop_oneof![
    bias => base.prop_map(Some),
    1 => Just(None),
  ]
}

/// default proptest strategy for i32: any value of the type
pub fn i32_strategy_default() -> impl Strategy<Value = i32>
{
  any::<i32>()
}

/// custom proptest strategy for i32 restricted to an inclusive range
pub fn i32_strategy_cust(range: core::ops::RangeInclusive<i32>) -> impl Strategy<Value = i32>
{
  range
}

pub fn TempControl_SysVerif_TempUnit_strategy_default() -> impl Strategy<Value = TempControl_SysVerif::TempUnit>
{
  TempControl_SysVerif_TempUnit_strategy_cust(1)
}

pub fn TempControl_SysVerif_TempUnit_strategy_cust(Fahrenheit_bias: u32) -> impl Strategy<Value = TempControl_SysVerif::TempUnit>
{
  prop_oneof![
    Fahrenheit_bias => Just(TempControl_SysVerif::TempUnit::Fahrenheit)
  ]
}

pub fn TempControl_SysVerif_FanAck_strategy_default() -> impl Strategy<Value = TempControl_SysVerif::FanAck>
{
  TempControl_SysVerif_FanAck_strategy_cust(1, 1)
}

pub fn TempControl_SysVerif_FanAck_strategy_cust(
  Ok_bias: u32,
  Error_bias: u32) -> impl Strategy<Value = TempControl_SysVerif::FanAck>
{
  prop_oneof![
    Ok_bias => Just(TempControl_SysVerif::FanAck::Ok),
    Error_bias => Just(TempControl_SysVerif::FanAck::Error)
  ]
}

pub fn TempControl_SysVerif_FanCmd_strategy_default() -> impl Strategy<Value = TempControl_SysVerif::FanCmd>
{
  TempControl_SysVerif_FanCmd_strategy_cust(1, 1)
}

pub fn TempControl_SysVerif_FanCmd_strategy_cust(
  On_bias: u32,
  Off_bias: u32) -> impl Strategy<Value = TempControl_SysVerif::FanCmd>
{
  prop_oneof![
    On_bias => Just(TempControl_SysVerif::FanCmd::On),
    Off_bias => Just(TempControl_SysVerif::FanCmd::Off)
  ]
}

/// default proptest strategy for bool: any value of the type
pub fn bool_strategy_default() -> impl Strategy<Value = bool>
{
  any::<bool>()
}

pub fn TempControl_SysVerif_Temperature_strategy_default() -> impl Strategy<Value = TempControl_SysVerif::Temperature>
{
  TempControl_SysVerif_Temperature_strategy_cust(
    any::<i32>(),
    TempControl_SysVerif_TempUnit_strategy_default()
  )
}

pub fn TempControl_SysVerif_Temperature_strategy_cust
  <degrees_i32_strategy: Strategy<Value = i32>, 
   unit_TempControl_SysVerif_TempUnit_strategy: Strategy<Value = TempControl_SysVerif::TempUnit>> (
  degrees_strategy: degrees_i32_strategy,
  unit_strategy: unit_TempControl_SysVerif_TempUnit_strategy) -> impl Strategy<Value = TempControl_SysVerif::Temperature>
{
  (degrees_strategy, unit_strategy).prop_map(|(degrees, unit)| {
    TempControl_SysVerif::Temperature { degrees, unit }
  })
}

pub fn TempControl_SysVerif_SetPoint_strategy_default() -> impl Strategy<Value = TempControl_SysVerif::SetPoint>
{
  TempControl_SysVerif_SetPoint_strategy_cust(
    TempControl_SysVerif_Temperature_strategy_default(),
    TempControl_SysVerif_Temperature_strategy_default()
  )
}

pub fn TempControl_SysVerif_SetPoint_strategy_cust
  <low_TempControl_SysVerif_Temperature_strategy: Strategy<Value = TempControl_SysVerif::Temperature>, 
   high_TempControl_SysVerif_Temperature_strategy: Strategy<Value = TempControl_SysVerif::Temperature>> (
  low_strategy: low_TempControl_SysVerif_Temperature_strategy,
  high_strategy: high_TempControl_SysVerif_Temperature_strategy) -> impl Strategy<Value = TempControl_SysVerif::SetPoint>
{
  (low_strategy, high_strategy).prop_map(|(low, high)| {
    TempControl_SysVerif::SetPoint { low, high }
  })
}

